// SPDX-License-Identifier: UNLICENSED
pragma solidity ^0.8.0;
import {Test} from "forge-std/Test.sol";
import {W_WALLET, Log} from "../src/W_WALLET.sol";

uint256 constant VALUE_CAP = 1000000000000000000000000000000;

contract InvMutTest is Test {
    W_WALLET c;
    function setUp() public { c = new W_WALLET(address(new Log())); }

    function testFuzz_property(uint256 amount, uint256 delta, uint256 baseTime, address actor) public {
        vm.assume(amount <= VALUE_CAP);
        vm.assume(actor != address(0));
        delta = bound(delta, 1, 36500 days);
        baseTime = bound(baseTime, 1, type(uint256).max - delta - 1);
        amount = bound(amount, 1, 10 ether);
        vm.warp(baseTime);
        uint256 unlockTime = baseTime + delta;
        vm.deal(actor, amount);
        vm.prank(actor);
        c.Put{value: amount}(unlockTime);
        (uint256 storedUnlockTime, ) = c.Acc(actor);
        assertTrue(storedUnlockTime >= unlockTime);
    }
}
